                'category': 'standard',
                'complete': False
            }
        }
    )
    print('=== Case 4: 50 standard incomplete ===')
    print(json.dumps(result4, ensure_ascii=False, indent=2))


if __name__ == '__main__':
    asyncio.run(main())

